std::atomic_size_t function_value_progress_callback_activations = 0u;
std::atomic_size_t function_value_progress_pulse_threads_started = 0u;
std::atomic_size_t function_value_detailed_cache_sessions_started = 0u;

bool analyzer_stack_diagnostics_enabled() noexcept {
    const auto* const value =
        std::getenv("CODEX_ANALYZER_STACK_DIAGNOSTICS");
    return value != nullptr && value[0] != '\0' &&
           !(value[0] == '0' && value[1] == '\0');
}

bool analyzer_fixpoint_trace_enabled() noexcept {
    // "1" keeps the bounded loss capsules useful for ordinary diagnostics.
    // The substantially noisier fixpoint stream is opt-in so redirected
    // stderr cannot dominate the analysis it is meant to measure.
    const auto* const value =
        std::getenv("CODEX_ANALYZER_STACK_DIAGNOSTICS");
    return value != nullptr &&
           (std::strcmp(value, "trace") == 0 ||
            std::strcmp(value, "verbose") == 0);
}

void emit_analyzer_fixpoint_trace(const char* const phase,
                                  const std::size_t iteration,
                                  const std::uint32_t function,
                                  const std::uint32_t block,
                                  const std::size_t pending) {
    if (!analyzer_fixpoint_trace_enabled()) return;
    const bool local = std::strcmp(phase, "local") == 0;
    const bool power_of_two =
        iteration != 0u && (iteration & (iteration - 1u)) == 0u;
    if (local) {
        if (iteration < 64u ||
            (!power_of_two && iteration % 65'536u != 0u))
            return;
    } else if (iteration > 16u &&
               !power_of_two && iteration % 128u != 0u) {
        return;
    }
    constexpr std::size_t maximum_fixpoint_trace_lines = 16'384u;
    static std::atomic_size_t emitted_lines = 0u;
    const auto line =
        emitted_lines.fetch_add(1u, std::memory_order_relaxed);
    if (line >= maximum_fixpoint_trace_lines) return;
    std::fprintf(stderr,
                 "KATANA_ANALYZER_FIXPOINT phase=%s iteration=%zu "
                 "function=0x%08X block=0x%08X pending=%zu\n",
                 phase,
                 iteration,
                 static_cast<unsigned int>(function),
                 static_cast<unsigned int>(block),
                 pending);
}

void emit_local_fixpoint_cap(const std::uint32_t function,
                             const std::uint32_t block,
                             const std::size_t iterations,
                             const std::size_t pending,
                             const std::uint8_t resolution_mode,
                             const bool guarded_inventory,
                             const bool contextual) noexcept {
    // A local cap already makes the current root fail closed. Always retain a
    // small raw-log capsule so a requested product run cannot lose the exact
    // evaluator merely because verbose diagnostics (which bypass the cache)
    // were intentionally disabled.
    constexpr std::size_t maximum_cap_capsules = 64u;
    static std::atomic_size_t emitted_capsules = 0u;
    const auto capsule =
        emitted_capsules.fetch_add(1u, std::memory_order_relaxed);
    if (capsule >= maximum_cap_capsules) return;
    std::fprintf(
        stderr,
        "KATANA_ANALYZER_LOCAL_FIXPOINT_CAP function=0x%08X "
        "block=0x%08X iterations=%zu pending=%zu resolution_mode=%u "
        "guarded_inventory=%u contextual=%u\n",
        static_cast<unsigned int>(function),
        static_cast<unsigned int>(block),
        iterations,
        pending,
        static_cast<unsigned int>(resolution_mode),
        static_cast<unsigned int>(guarded_inventory),
        static_cast<unsigned int>(contextual));
}

void emit_incomplete_resolution_root(
    const char* const stage,
    const std::size_t root_index,
    const std::uint32_t root_address,
    const bool local_fixpoint,
    const GuardedCodeInventoryWalkDiagnostics& walk,
    const bool candidate_inventory_truncated,
    const bool candidate_budget_exhausted,
    const bool raw_stored_candidates_truncated,
    const bool table_scan_truncated) noexcept {
    // Product runs must retain the first concrete loss capsule even when
    // verbose diagnostics are disabled.  The previous DeltaOnly path reduced
    // every cause to `incomplete-root` and then discarded the only object
    // which still knew the owner and the actual truncation bit.
    constexpr std::size_t maximum_capsules = 64u;
    static std::atomic_size_t emitted_capsules = 0u;
    const auto capsule =
        emitted_capsules.fetch_add(1u, std::memory_order_relaxed);
    if (capsule >= maximum_capsules) return;
    std::fprintf(
        stderr,
        "KATANA_ANALYZER_INCOMPLETE_ROOT stage=%s index=%zu root=0x%08X "
        "local_fixpoint=%u pending_regions=%zu region_block_limited=%zu "
        "forwarded_context_limited=%zu contextual_context_limited=%zu "
        "contextual_evaluation_limited=%zu abi_stack_projection=%zu "
        "local_fixpoint_limited=%zu local_fixpoint_max=%zu "
        "local_fixpoint_budget=%zu "
        "root_logical_budget_exhausted=%u "
        "candidate_values_truncated=%u abi_stack_base_unresolved=%u "
        "tail_target_unresolved=%u candidate_inventory_truncated=%u "
        "candidate_budget_exhausted=%u raw_stored_truncated=%u "
        "table_scan_truncated=%u\n",
        stage,
        root_index,
        static_cast<unsigned int>(root_address),
        static_cast<unsigned int>(local_fixpoint),
        walk.pending_inventory_region_count,
        walk.inventory_region_block_limited_regions,
        walk.forwarded_store_context_limited_functions,
        walk.contextual_return_context_limited_functions,
        walk.contextual_return_evaluation_limited_functions,
        walk.abi_stack_argument_projection_truncated_functions,
        walk.local_fixpoint_limited_evaluations,
        walk.maximum_local_fixpoint_iterations,
        walk.local_fixpoint_iteration_budget,
        static_cast<unsigned int>(
            walk.resolution_root_logical_budget_exhausted),
        static_cast<unsigned int>(
            walk.inventory_candidate_values_truncated),
        static_cast<unsigned int>(walk.abi_stack_base_unresolved),
        static_cast<unsigned int>(walk.inventory_tail_target_unresolved),
        static_cast<unsigned int>(candidate_inventory_truncated),
        static_cast<unsigned int>(candidate_budget_exhausted),
        static_cast<unsigned int>(raw_stored_candidates_truncated),
        static_cast<unsigned int>(table_scan_truncated));
}

constexpr std::size_t maximum_detailed_analyzer_diagnostics = 64u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_candidate_truncation = 4u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_tail_store_identity_loss = 5u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_contextual_value_overflow = 6u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_candidate_store = 7u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_candidate_r0_indexed_store = 8u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_candidate_r0_indexed_load = 9u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_fixpoint_call = 10u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_forwarded_call = 11u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_forwarded_tail = 12u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_inventory_sp_loss = 14u;
constexpr std::uint8_t
    detailed_analyzer_diagnostic_kind_baseline_candidate_truncation = 15u;

using DetailedAnalyzerDiagnosticKey =
    std::tuple<std::uint8_t,
               std::uint32_t,
               std::uint32_t,
               std::uint32_t,
               std::uint8_t>;

struct DetailedAnalyzerDiagnosticState {
    std::mutex mutex;
    std::set<DetailedAnalyzerDiagnosticKey> emitted;
    std::map<std::uint8_t, std::size_t> emitted_by_kind;
    std::uint64_t epoch = 0u;
};

DetailedAnalyzerDiagnosticState& detailed_analyzer_diagnostic_state() {
    static DetailedAnalyzerDiagnosticState state;
    return state;
}

void begin_detailed_analyzer_diagnostic_epoch() {
    if (!analyzer_stack_diagnostics_enabled()) return;
    auto& state = detailed_analyzer_diagnostic_state();
    const std::lock_guard lock(state.mutex);
    state.emitted.clear();
    state.emitted_by_kind.clear();
    ++state.epoch;
    std::fprintf(stderr,
                 "KATANA_ANALYZER_DIAGNOSTIC_EPOCH id=%llu\n",
                 static_cast<unsigned long long>(state.epoch));
}

void emit_bounded_analyzer_diagnostic(
    const std::uint8_t kind,
    const std::uint32_t owner,
    const std::uint32_t site,
    const std::uint32_t target,
    const std::uint8_t reason,
    const std::function<void()>& emit) {
    if (!analyzer_stack_diagnostics_enabled()) return;
    auto& state = detailed_analyzer_diagnostic_state();
    const std::lock_guard lock(state.mutex);
    auto& emitted_for_kind = state.emitted_by_kind[kind];
    if (emitted_for_kind >= maximum_detailed_analyzer_diagnostics ||
        !state.emitted.emplace(kind, owner, site, target, reason).second)
        return;
    ++emitted_for_kind;
    emit();
}

void emit_analyzer_stack_diagnostic(const char* const kind,
                                    const std::uint32_t owner,
                                    const std::uint32_t site,
                                    const std::uint32_t target) {
    if (!analyzer_stack_diagnostics_enabled()) return;
    const auto diagnostic_kind = [&] {
        if (std::strcmp(kind, "candidate-store") == 0)
            return detailed_analyzer_diagnostic_kind_candidate_store;
        if (std::strcmp(kind, "candidate-r0-indexed-store") == 0)
            return detailed_analyzer_diagnostic_kind_candidate_r0_indexed_store;
        if (std::strcmp(kind, "candidate-r0-indexed-load") == 0)
            return detailed_analyzer_diagnostic_kind_candidate_r0_indexed_load;
        if (std::strcmp(kind, "fixpoint-call") == 0)
            return detailed_analyzer_diagnostic_kind_fixpoint_call;
        if (std::strcmp(kind, "forwarded-call") == 0)
            return detailed_analyzer_diagnostic_kind_forwarded_call;
        if (std::strcmp(kind, "forwarded-tail") == 0)
            return detailed_analyzer_diagnostic_kind_forwarded_tail;
        return static_cast<std::uint8_t>(13u);
    }();
    emit_bounded_analyzer_diagnostic(
        diagnostic_kind, owner, site, target, 0u, [&] {
            std::fprintf(stderr,
                         "KATANA_ANALYZER_STACK_LOSS kind=%s owner=0x%08X "
                         "site=0x%08X target=0x%08X\n",
                         kind,
                         static_cast<unsigned int>(owner),
                         static_cast<unsigned int>(site),
                         static_cast<unsigned int>(target));
        });
}

void emit_contextual_return_limit_diagnostic(
    const char* const reason,
    const std::uint8_t reason_id,
    const std::uint32_t owner,
    const std::uint32_t current,
    const std::uint32_t target,
    const std::size_t context_count,
    const std::size_t evaluation_count,
    const std::size_t pending_count) {
    emit_bounded_analyzer_diagnostic(
        2u,
        owner,
        current,
        target,
        reason_id,
        [&] {
            std::fprintf(
                stderr,
                "KATANA_ANALYZER_CONTEXT_LIMIT reason=%s owner=0x%08X "
                "current=0x%08X target=0x%08X contexts=%zu "
                "evaluations=%zu pending=%zu\n",
                reason,
                static_cast<unsigned int>(owner),
                static_cast<unsigned int>(current),
                static_cast<unsigned int>(target),
                context_count,
                evaluation_count,
                pending_count);
        });
}

constexpr std::size_t maximum_summary_values = 8u;
constexpr std::size_t maximum_guarded_code_inventory = 1'024u;
// Saved-stack pointers are value trees, but analysis never needs an unbounded
// dereference chain.  This is a representation cap, not a second candidate
// budget; the existing guarded-inventory bound remains the candidate cap.
constexpr std::size_t maximum_saved_stack_epoch_nesting = 4u;
constexpr std::size_t maximum_saved_stack_epoch_nodes =
    maximum_guarded_code_inventory;
constexpr std::size_t maximum_saved_stack_epoch_slots =
    maximum_guarded_code_inventory;
constexpr std::size_t maximum_raw_stored_code_candidates =
    maximum_guarded_code_inventory * 4u;
constexpr std::size_t reserved_returned_table_targets = 256u;
constexpr std::int32_t maximum_stack_distance = 65'536;
constexpr std::size_t maximum_fixpoint_iterations = 65'536u;
constexpr std::size_t maximum_local_fixpoint_iterations = 65'536u;
// ABI stack arguments are four-byte slots in the already bounded
// [0, maximum_stack_distance] domain. The projection/read-set budget covers
// that complete semantic domain; the smaller flow-state cap below is only an
// implementation guard for transient local taints.
constexpr std::size_t maximum_abi_stack_argument_slots =
    static_cast<std::size_t>(maximum_stack_distance) / 4u + 1u;
constexpr std::size_t maximum_abi_persistent_flow_stack_slots = 256u;
static_assert(maximum_abi_persistent_flow_stack_slots <
              maximum_abi_stack_argument_slots);
constexpr std::int32_t contextual_incomplete_stack_prefix_bytes = 64;
static_assert((contextual_incomplete_stack_prefix_bytes & 3) == 0);
constexpr std::size_t maximum_forwarded_store_contexts =
    maximum_guarded_code_inventory;
// Semantic contexts, their distinct isolated roots and re-evaluations are
// independently bounded. Any loss is reported through the existing forwarding
// truncation contract and blocks a product export.
constexpr std::size_t maximum_forwarded_store_context_root_call_sites =
    64u;
constexpr std::size_t maximum_forwarded_store_context_evaluations =
    64u;
// Root/callsite/callee provenance is observational metadata, but it used to
// make otherwise identical forwarded-inventory states physically distinct.
// A bounded, collision-free symbolic token space lets the shared evaluation
// cache interpret the semantic state once and expand the exact provenance for
// every logical root afterwards. Exhausting this optimization budget is a
// cache miss/fallback only; it never truncates analysis evidence.
constexpr std::size_t maximum_forwarded_evidence_tokens =
    maximum_fixpoint_iterations;
constexpr std::size_t maximum_contextual_return_evaluations =
    maximum_fixpoint_iterations;
constexpr std::size_t maximum_inventory_stack_coordinates = 64u;
constexpr std::size_t maximum_inventory_regions = maximum_guarded_code_inventory;
constexpr std::size_t maximum_inventory_region_blocks = 256u;
// Small exact CFA discoveries must remain proportional to their changed
// closure. Larger seed waves already carry material delta work and keep the
// established bulk builder, which is more efficient for that domain.
constexpr std::size_t maximum_local_derived_topology_lines = 512u;
constexpr std::size_t maximum_local_derived_topology_functions = 8u;
constexpr std::size_t maximum_memory_values = 256u;
constexpr std::size_t maximum_parallel_resolution_jobs = 64u;
constexpr std::size_t minimum_parallel_resolution_functions = 2u;
constexpr std::size_t maximum_abi_stack_read_top_chain = 16u;
constexpr std::size_t maximum_evaluation_inventory_replay_bytes =
    256u * 1024u * 1024u;
enum class AbiStackReadTopReason : std::uint8_t {
    None,
    InvalidSlot,
    SlotBudget,
    LocalStackCoordinate,
    CalleeSetIncomplete,
    EmptyCalleeSet,
    ReadMapUnavailable,
    CalleeMissing,
    CalleeTop,
    CallerStackCoordinate,
    ComposeRange,
    MissingBlock,
    MissingDelay,
    IndirectNoIngress,
    ExternalSuccessorNoIngress,
    FixpointSlotBudget
};

[[nodiscard]] const char* abi_stack_read_top_reason_name(
    const AbiStackReadTopReason reason) noexcept {
    switch (reason) {
    case AbiStackReadTopReason::None: return "none";
    case AbiStackReadTopReason::InvalidSlot: return "invalid-slot";
    case AbiStackReadTopReason::SlotBudget: return "slot-budget";
    case AbiStackReadTopReason::LocalStackCoordinate:
        return "local-stack-coordinate";
    case AbiStackReadTopReason::CalleeSetIncomplete:
        return "callee-set-incomplete";
    case AbiStackReadTopReason::EmptyCalleeSet:
        return "empty-callee-set";
    case AbiStackReadTopReason::ReadMapUnavailable:
        return "read-map-unavailable";
    case AbiStackReadTopReason::CalleeMissing: return "callee-missing";
    case AbiStackReadTopReason::CalleeTop: return "callee-top";
    case AbiStackReadTopReason::CallerStackCoordinate:
        return "caller-stack-coordinate";
    case AbiStackReadTopReason::ComposeRange: return "compose-range";
    case AbiStackReadTopReason::MissingBlock: return "missing-block";
    case AbiStackReadTopReason::MissingDelay: return "missing-delay";
    case AbiStackReadTopReason::IndirectNoIngress:
        return "indirect-no-ingress";
    case AbiStackReadTopReason::ExternalSuccessorNoIngress:
        return "external-successor-no-ingress";
    case AbiStackReadTopReason::FixpointSlotBudget:
        return "fixpoint-slot-budget";
    }
    return "unknown";
}

struct AbiStackReadTopFrame {
    AbiStackReadTopReason reason = AbiStackReadTopReason::None;
    std::uint32_t owner = 0u;
    std::uint32_t site = 0u;
    std::uint32_t target = 0u;
    bool contract_present = false;
    bool contract_complete = false;
    bool ingress_present = false;
    bool ingress_guarded = false;
    bool ingress_complete = false;
    bool residual_indirect = false;
    bool external_successor = false;
};

// A complete set contains every non-negative, word-aligned stack argument
// slot which a callee can read before it is definitely overwritten. An
// incomplete set is conservative Top and must retain the legacy full
// projection; it is never equivalent to an empty set.
struct AbiStackArgumentReadSet {
    std::vector<std::int32_t> slots;
    bool complete = true;
    // Diagnostic-only provenance. It is deliberately excluded from semantic
    // equality so enabling diagnostics cannot alter fixed-point convergence.
    std::vector<AbiStackReadTopFrame> top_chain;
    bool top_chain_truncated = false;

    bool operator==(const AbiStackArgumentReadSet& other) const {
        return slots == other.slots && complete == other.complete;
    }
};

using AbiStackArgumentReadMap =
    std::unordered_map<std::uint32_t, AbiStackArgumentReadSet>;
using ForwardedRegisterReadMap =
    std::unordered_map<std::uint32_t, std::uint16_t>;

void make_abi_stack_argument_reads_unknown(
    AbiStackArgumentReadSet& reads) {
    reads.slots.clear();
    reads.complete = false;
}

void set_abi_stack_read_top_reason(
    AbiStackReadTopReason* const destination,
    const AbiStackReadTopReason reason) {
    if (destination != nullptr &&
        *destination == AbiStackReadTopReason::None)
        *destination = reason;
}

void record_abi_stack_read_top(
    AbiStackArgumentReadSet& reads,
    const AbiStackReadTopFrame frame,
    const AbiStackArgumentReadSet* const parent = nullptr) {
    if (!analyzer_stack_diagnostics_enabled() ||
        frame.reason == AbiStackReadTopReason::None ||
        !reads.top_chain.empty())
        return;
    reads.top_chain.push_back(frame);
    if (parent == nullptr) return;
    for (const auto& parent_frame : parent->top_chain) {
        if (reads.top_chain.size() >= maximum_abi_stack_read_top_chain) {
            reads.top_chain_truncated = true;
            break;
        }
        if (parent_frame.owner == frame.owner) {
            reads.top_chain_truncated = true;
            break;
        }
        reads.top_chain.push_back(parent_frame);
    }
    reads.top_chain_truncated =
        reads.top_chain_truncated || parent->top_chain_truncated;
}

void copy_abi_stack_read_top(
    AbiStackArgumentReadSet& destination,
    const AbiStackArgumentReadSet& source) {
    if (!analyzer_stack_diagnostics_enabled() ||
        !destination.top_chain.empty())
        return;
    destination.top_chain = source.top_chain;
    destination.top_chain_truncated = source.top_chain_truncated;
}

bool insert_abi_stack_argument_read(AbiStackArgumentReadSet& reads,
                                    const std::int64_t slot,
                                    AbiStackReadTopReason* const
                                        top_reason = nullptr) {
    if (!reads.complete) return false;
    if (slot < 0 || slot > maximum_stack_distance || (slot & 3) != 0) {
        set_abi_stack_read_top_reason(
            top_reason, AbiStackReadTopReason::InvalidSlot);
        make_abi_stack_argument_reads_unknown(reads);
        return false;
    }
    const auto value = static_cast<std::int32_t>(slot);
    const auto position =
        std::lower_bound(reads.slots.begin(), reads.slots.end(), value);
    if (position != reads.slots.end() && *position == value) return false;
    if (reads.slots.size() >= maximum_abi_stack_argument_slots) {
        set_abi_stack_read_top_reason(
            top_reason, AbiStackReadTopReason::SlotBudget);
        make_abi_stack_argument_reads_unknown(reads);
        return false;
    }
    reads.slots.insert(position, value);
    return true;
}

bool merge_abi_stack_argument_reads(
    AbiStackArgumentReadSet& destination,
    const AbiStackArgumentReadSet& source) {
    if (!destination.complete) return false;
    if (!source.complete) {
        make_abi_stack_argument_reads_unknown(destination);
        copy_abi_stack_read_top(destination, source);
        return true;
    }
    const auto previous = destination;
    for (const auto slot : source.slots) {
        static_cast<void>(
            insert_abi_stack_argument_read(destination, slot));
        if (!destination.complete) break;
    }
    return destination != previous;
}

template <typename FunctionRange>
std::vector<std::vector<std::uint32_t>>
strong_components(const FunctionRange& functions) {
    std::unordered_map<std::uint32_t, const FunctionInfo*> by_address;
    by_address.reserve(functions.size());
    for (const auto& function : functions)
        by_address.emplace(function.entry_address, &function);
    std::unordered_map<std::uint32_t, std::size_t> index;
    std::unordered_map<std::uint32_t, std::size_t> lowlink;
    std::unordered_set<std::uint32_t> on_stack;
    std::vector<std::uint32_t> stack;
    std::vector<std::vector<std::uint32_t>> components;
    index.reserve(functions.size());
    lowlink.reserve(functions.size());
    on_stack.reserve(functions.size());
    stack.reserve(functions.size());
    components.reserve(functions.size());
    std::size_t next_index = 0u;
    std::function<void(std::uint32_t)> visit = [&](const std::uint32_t address) {
        index.emplace(address, next_index);
        lowlink.emplace(address, next_index++);
        stack.push_back(address);
        on_stack.insert(address);
        const auto found = by_address.find(address);
        if (found != by_address.end()) {
            for (const auto callee : found->second->direct_callees) {
                if (!by_address.contains(callee)) continue;
                if (!index.contains(callee)) {
                    visit(callee);
                    lowlink[address] = std::min(lowlink[address], lowlink[callee]);
                } else if (on_stack.contains(callee)) {
                    lowlink[address] = std::min(lowlink[address], index[callee]);
                }
            }
        }
        if (lowlink[address] != index[address]) return;
        auto& component = components.emplace_back();
        for (;;) {
            const auto member = stack.back();
            stack.pop_back();
            on_stack.erase(member);
            component.push_back(member);
            if (member == address) break;
        }
        std::sort(component.begin(), component.end());
    };
    for (const auto& function : functions) {
        if (!index.contains(function.entry_address)) visit(function.entry_address);
    }
    std::reverse(components.begin(), components.end());
    return components;
}

struct InventorySavedStackEpoch;

struct InventorySavedStackSlot {
    std::int32_t relative_slot = 0;
    // The internal slot deliberately mirrors the public summary slot.  In
    // particular, pre-ABI ordinary scalars remain relative to this exact
    // saved-stack identity instead of being flattened into the epoch root.
    InventoryCandidateCarrier carrier;
    std::vector<InventorySavedStackEpoch> nested_epochs;

    bool operator==(const InventorySavedStackSlot&) const = default;
};

struct InventorySavedStackEpoch {
    // A pending epoch is attached only to a detached value that is known to
    // have denoted a current stack coordinate when it was stored. Its slots
    // are candidate-only and already relative to that saved pointer.
    bool present = false;
    bool unresolved = false;
    // True only while the captured coordinates still refer to the currently
    // active AbstractState stack namespace. A stack switch detaches every
    // surviving reference before the new epoch starts.
    bool tracks_current_epoch = false;
    // Sticky evidence that finite callback candidates were discarded when
    // this epoch reached its terminal unresolved top. A consumed top with no
    // candidate loss need not poison unrelated inventory sinks.
    bool candidate_payload_lost = false;
    bool nested_saved_stack_alias_latent = false;
    bool nested_saved_stack_alias_tracks_current_epoch = false;
    std::vector<InventorySavedStackSlot> slots;
    // Finite slot payloads whose relative coordinate could no longer be
    // represented.  This remains epoch-scoped: it must never be materialized
    // as a direct branch value merely because the original slot was lost.
    InventoryCandidateCarrier unresolved_candidate_carrier;
    std::vector<InventorySavedStackEpoch> unresolved_nested_epochs;

    bool operator==(const InventorySavedStackEpoch&) const = default;
};

struct AbstractValue {
    bool known = false;
    bool guarded = false;
    bool complete = false;
    // Inventory-only must-provenance: the value is derived from the
    // architectural stack pointer on every joined path. This is narrower than
    // "may alias stack" and lets guarded code-pointer inventory distinguish an
    // actual stack spill from a mixed stack/object-pointer join.
    bool inventory_stack_derived = false;
    // Inventory-only evidence that the value crossed a native-code argument
    // boundary as a finite, decode-valid address.  Generic call-site
    // provenance is deliberately not strong enough for this purpose.
    bool inventory_code_pointer = false;
    // Inventory-only evidence that this value came from a 32-bit PC-relative
    // image literal and already denoted a decode-valid native-code candidate.
    // It is not a code-pointer proof by itself; a real call/tail ABI boundary
    // must still promote it.
    bool inventory_pc_relative_code_literal = false;
    std::vector<std::uint32_t> inventory_code_pointer_values;
    std::vector<std::uint32_t> inventory_pc_relative_code_literal_values;
    bool inventory_code_pointer_values_truncated = false;
    bool inventory_pc_relative_code_literal_values_truncated = false;
    // Context-only candidate-return taint. It never proves a dispatch edge or
    // a code pointer; it only keeps the bounded helper slice attached to the
    // ABI values that originated at a guarded candidate call.
    bool contextual_candidate_dependency = false;
    // Value-scoped fail-closed provenance. Unlike the state-wide unresolved
    // stack pool, this bit dies when the value is overwritten and therefore
    // cannot poison an unrelated later inventory sink.
    bool inventory_stack_callback_loss_unresolved = false;
    // Inventory-only suspended-stack payload. It cannot make this value known
    // and cannot establish a semantic memory or control-flow fact.
    InventorySavedStackEpoch inventory_saved_stack_epoch;
    std::vector<std::uint32_t> values;
    std::set<std::uint32_t> call_sites;
    std::set<std::uint32_t> callees;

    bool operator==(const AbstractValue&) const = default;
};

// A canonical, upward-closed summary for stack cells that can no longer be
// represented one-by-one.  `present` is semantically meaningful even when
// the payload is empty: it prevents a later widening from resurrecting an
// unbounded sequence of explicit keys above `lower_bound`.
struct StackTailSummary final {
    bool present = false;
    std::int32_t lower_bound = 0;
    AbstractValue payload;

    bool operator==(const StackTailSummary&) const = default;
};

constexpr std::uint8_t unresolved_saved_stack_alias_source_stack = 1u;
constexpr std::uint8_t unresolved_saved_stack_alias_source_memory = 2u;

struct AbstractState {
    std::array<AbstractValue, 16u> registers;
    std::array<std::optional<std::int32_t>, 16u> stack_offsets;
    // A separate coordinate system for the guarded inventory.  Writable
    // captured literals may advance this proof, but never the authoritative
    // stack offsets used by ordinary CFG and memory reasoning.
    std::array<std::optional<std::int32_t>, 16u> inventory_stack_offsets;
    // FPSCR.SZ-dependent FMOV stack updates can have more than one concrete
    // coordinate. These candidates remain inventory-only: they may retain
    // guarded callback provenance, but never establish semantic memory or CFG
    // facts. A non-empty set is definite only because merge_state drops it
    // whenever any incoming path lacks a stack coordinate.
    std::array<std::vector<std::int32_t>, 16u>
        inventory_stack_offset_candidates;
    std::array<bool, 16u> stack_may_alias = [] {
        std::array<bool, 16u> result{};
        result.fill(true);
        return result;
    }();
    // This narrower provenance is consumed only by the guarded native-code
    // inventory observers.  In particular it must never make ordinary stack,
    // memory or control-flow reasoning less conservative.
    std::array<bool, 16u> inventory_stack_may_alias = [] {
        std::array<bool, 16u> result{};
        result.fill(true);
        return result;
    }();
    // Internal, inventory-only proof that a register still denotes VBR plus a
    // constant displacement.  It is deliberately not part of the public value
    // summaries and must never create a fixed control-flow edge.
    std::array<bool, 16u> inventory_vbr_relative{};
    // Inventory-only provenance for a pointer/reference path seeded by a
    // finite PC-relative storage address. It is neither a non-stack proof nor
    // code-pointer provenance for a loaded value; it only permits direct
    // PC-relative callback-literal stores as guarded inventory candidates.
    std::array<bool, 16u> inventory_fixed_storage_reference{};
    std::map<std::int32_t, AbstractValue> stack_values;
    StackTailSummary stack_tail;
    std::map<std::uint32_t, AbstractValue> memory_values;
    // May-carriers are storage-domain facts, not value-scoped loss.  An
    // imprecise stack/memory store can still be loaded later as a bounded
    // guarded candidate without pretending to know its exact cell identity.
    InventoryCandidateCarrier inventory_unresolved_stack_carrier;
    InventoryCandidateCarrier inventory_unresolved_memory_carrier;
    // A stored suspended stack pointer needs the same separation: preserve
    // the epoch payload as an epoch rather than reclassifying its slots as
    // direct callbacks.
    InventorySavedStackEpoch inventory_unresolved_stack_epoch;
    InventorySavedStackEpoch inventory_unresolved_memory_epoch;
    // Evaluation-local relative write effect. This metadata is reset at every
    // callee ABI boundary and is never part of an ingress cache identity.
    bool memory_write_unknown = false;
    std::vector<FunctionMemoryWriteRange> memory_write_ranges;
    // Path-local must fact used only to suppress reads of bytes already
    // defined inside this evaluation. It is intersected at CFG joins and is
    // never part of an ingress cache identity.
    std::vector<FunctionMemoryWriteRange>
        memory_definitely_written_ranges;
    // A payload-free saved-SP alias whose exact bounded cell identity was
    // widened away. Unlike callback loss, this is harmless until the current
    // stack epoch later receives a relevant callback candidate. Source bits
    // allow unknown stack/memory loads to materialize the latent value again.
    std::uint8_t inventory_unresolved_saved_stack_alias_sources = 0u;
    std::uint8_t inventory_unresolved_saved_stack_alias_tracks_current_sources = 0u;
    // Ephemeral callee-local watcher for exact saved-SP aliases that were
    // intentionally omitted by a complete ABI read projection. It upgrades
    // to real loss on mutation, but is never exported through a function
    // summary: the caller still owns the exact alias.
    bool inventory_current_stack_epoch_alias_watcher = false;
    // The watched alias can outlive a temporary stack switch. Keep that
    // possibility separate from the currently active epoch so writes on an
    // unrelated resumed stack do not immediately become loss. Restoring any
    // saved epoch rearms the current watcher conservatively.
    bool inventory_detached_stack_epoch_alias_watcher = false;
    bool inventory_unresolved_stack_callback_loss = false;
    // Memory-domain direct Top is intentionally distinct from the active
    // stack-domain direct Top. A stack switch discards only the latter.
    bool inventory_unresolved_memory_callback_loss = false;
    // Sticky domain-scoped evidence that an exact slot/cell identity carrying
    // direct loss exceeded its bounded domain (stack=1, memory=2).
    std::uint8_t inventory_callback_loss_identity_truncated_sources = 0u;

    AbstractState() {
        registers[15u].inventory_stack_derived = true;
        inventory_stack_offsets[15u] = 0;
    }

    AbstractValue& operator[](const std::size_t index) {
        return registers[index];
    }
    const AbstractValue& operator[](const std::size_t index) const {
        return registers[index];
    }
    auto begin() noexcept {
        return registers.begin();
    }
    auto end() noexcept {
        return registers.end();
    }
    auto begin() const noexcept {
        return registers.begin();
    }
    auto end() const noexcept {
        return registers.end();
    }
    constexpr std::size_t size() const noexcept {
        return registers.size();
    }

    bool operator==(const AbstractState&) const = default;
};

[[nodiscard]] bool valid_memory_write_range(
    const FunctionMemoryWriteRange& range) noexcept {
    return range.width != 0u &&
           static_cast<std::uint64_t>(range.address) + range.width <=
               (std::uint64_t{1u} << 32u);
}

void normalize_memory_write_ranges(
    std::vector<FunctionMemoryWriteRange>& ranges) {
    std::erase_if(ranges, [](const auto& range) {
        return !valid_memory_write_range(range);
    });
    std::sort(ranges.begin(), ranges.end());
    std::vector<FunctionMemoryWriteRange> normalized;
    normalized.reserve(ranges.size());
    for (const auto& range : ranges) {
        if (normalized.empty()) {
            normalized.push_back(range);
            continue;
        }
        auto& previous = normalized.back();
        const auto previous_end =
            static_cast<std::uint64_t>(previous.address) + previous.width;
        const auto range_end =
            static_cast<std::uint64_t>(range.address) + range.width;
        if (static_cast<std::uint64_t>(range.address) > previous_end) {
            normalized.push_back(range);
            continue;
        }
        const auto merged_width =
            std::max(previous_end, range_end) - previous.address;
        if (merged_width >
            std::numeric_limits<std::uint32_t>::max()) {
            // The public range format cannot encode the complete 4-GiB
            // domain in one width. Keep two valid adjacent ranges instead of
            // wrapping the width to zero.
            normalized.push_back(range);
            continue;
        }
        previous.width = static_cast<std::uint32_t>(merged_width);
    }
    ranges = std::move(normalized);
}

void mark_unknown_memory_write(AbstractState& state) {
    state.memory_write_unknown = true;
    state.memory_write_ranges.clear();
}

void record_memory_write_range(AbstractState& state,
                               const std::uint32_t address,
                               const std::size_t width) {
    if (state.memory_write_unknown) return;
    if (width == 0u ||
        width > std::numeric_limits<std::uint32_t>::max() ||
        static_cast<std::uint64_t>(address) + width >
            (std::uint64_t{1u} << 32u)) {
        mark_unknown_memory_write(state);
        return;
    }
    state.memory_write_ranges.push_back(
        {address, static_cast<std::uint32_t>(width)});
    normalize_memory_write_ranges(state.memory_write_ranges);
    if (state.memory_write_ranges.size() > maximum_memory_values)
        mark_unknown_memory_write(state);
}

bool merge_memory_write_effect(AbstractState& destination,
                               const AbstractState& source) {
    if (destination.memory_write_unknown) return false;
    if (source.memory_write_unknown) {
        mark_unknown_memory_write(destination);
        return true;
    }
    auto merged = destination.memory_write_ranges;
    merged.insert(merged.end(),
                  source.memory_write_ranges.begin(),
                  source.memory_write_ranges.end());
    normalize_memory_write_ranges(merged);
    if (merged.size() > maximum_memory_values) {
        mark_unknown_memory_write(destination);
        return true;
    }
    if (merged == destination.memory_write_ranges) return false;
    destination.memory_write_ranges = std::move(merged);
    return true;
}

struct MemoryReadObservation final {
    bool complete = true;
    bool unknown = false;
    std::vector<FunctionMemoryWriteRange> ranges;
};

void mark_memory_read_incomplete(
    MemoryReadObservation* const observation) {
    if (observation != nullptr && !observation->unknown)
        observation->complete = false;
}

void mark_unknown_memory_read(
    MemoryReadObservation* const observation) {
    if (observation == nullptr) return;
    observation->complete = true;
    observation->unknown = true;
    observation->ranges.clear();
}

[[nodiscard]] bool insert_normalized_memory_range(
    std::vector<FunctionMemoryWriteRange>& ranges,
    const std::uint32_t address,
    const std::size_t width) {
    if (width == 0u ||
        width > std::numeric_limits<std::uint32_t>::max() ||
        static_cast<std::uint64_t>(address) + width >
            (std::uint64_t{1u} << 32u))
        return false;
    auto begin = static_cast<std::uint64_t>(address);
    auto end = begin + width;
    auto first = std::lower_bound(
        ranges.begin(), ranges.end(), begin,
        [](const auto& range, const std::uint64_t candidate) {
            return static_cast<std::uint64_t>(range.address) +
                       range.width <
                   candidate;
        });
    auto last = first;
    while (last != ranges.end() &&
           static_cast<std::uint64_t>(last->address) <= end) {
        begin = std::min(begin,
                         static_cast<std::uint64_t>(last->address));
        end = std::max(
            end,
            static_cast<std::uint64_t>(last->address) + last->width);
        ++last;
    }
    if (end - begin > std::numeric_limits<std::uint32_t>::max())
        return false;
    const FunctionMemoryWriteRange merged{
        static_cast<std::uint32_t>(begin),
        static_cast<std::uint32_t>(end - begin)};
    if (first != last && std::next(first) == last &&
        *first == merged)
        return true;
    const auto index = static_cast<std::size_t>(
        std::distance(ranges.begin(), first));
    ranges.erase(first, last);
    ranges.insert(ranges.begin() +
                      static_cast<std::ptrdiff_t>(index),
                  merged);
    return true;
}

[[nodiscard]] bool memory_range_fully_covered(
    const std::span<const FunctionMemoryWriteRange> ranges,
    const std::uint32_t address,
    const std::size_t width) noexcept {
    if (width == 0u ||
        width > std::numeric_limits<std::uint32_t>::max() ||
        static_cast<std::uint64_t>(address) + width >
            (std::uint64_t{1u} << 32u))
        return false;
    const auto end = static_cast<std::uint64_t>(address) + width;
    const auto candidate = std::upper_bound(
        ranges.begin(), ranges.end(), address,
        [](const std::uint32_t value, const auto& range) {
            return value < range.address;
        });
    if (candidate == ranges.begin()) return false;
    const auto& range = *std::prev(candidate);
    return range.address <= address &&
           static_cast<std::uint64_t>(range.address) + range.width >= end;
}

void record_memory_read_range(MemoryReadObservation* const observation,
                              const AbstractState& state,
                              const std::uint32_t address,
                              const std::size_t width) {
    if (observation == nullptr || observation->unknown ||
        memory_range_fully_covered(
            state.memory_definitely_written_ranges, address, width))
        return;
    if (!insert_normalized_memory_range(
            observation->ranges, address, width)) {
        mark_unknown_memory_read(observation);
        return;
    }
    if (observation->ranges.size() > maximum_memory_values)
        mark_unknown_memory_read(observation);
}

void record_definite_memory_write_range(AbstractState& state,
                                        const std::uint32_t address,
                                        const std::size_t width) {
    if (width == 0u ||
        width > std::numeric_limits<std::uint32_t>::max() ||
        static_cast<std::uint64_t>(address) + width >
            (std::uint64_t{1u} << 32u)) {
        state.memory_definitely_written_ranges.clear();
        return;
    }
    if (!insert_normalized_memory_range(
            state.memory_definitely_written_ranges,
            address,
            width) ||
        state.memory_definitely_written_ranges.size() >
            maximum_memory_values)
        state.memory_definitely_written_ranges.clear();
}

void merge_memory_read_contract(
    MemoryReadObservation* const observation,
    const bool complete,
    const bool unknown,
    const std::span<const FunctionMemoryWriteRange> ranges,
    const AbstractState* const state = nullptr) {
    if (observation == nullptr || observation->unknown) return;
    if (unknown) {
        mark_unknown_memory_read(observation);
        return;
    }
    if (!complete) mark_memory_read_incomplete(observation);
    for (const auto& range : ranges) {
        if (state != nullptr) {
            record_memory_read_range(
                observation, *state, range.address, range.width);
        } else if (!insert_normalized_memory_range(
                       observation->ranges,
                       range.address,
                       range.width) ||
                   observation->ranges.size() >
                       maximum_memory_values) {
            mark_unknown_memory_read(observation);
            return;
        }
    }
}

void widen_function_memory_read_contract(
    FunctionValueSummary& destination,
    const FunctionValueSummary& previous) {
    MemoryReadObservation widened{
        destination.memory_read_complete,
        destination.memory_read_unknown,
        destination.memory_read_ranges};
    merge_memory_read_contract(
        &widened,
        previous.memory_read_complete,
        previous.memory_read_unknown,
        previous.memory_read_ranges);
    destination.memory_read_complete = widened.complete;
    destination.memory_read_unknown = widened.unknown;
    destination.memory_read_ranges = std::move(widened.ranges);
}

bool merge_definite_memory_writes(AbstractState& destination,
                                  const AbstractState& source) {
    std::vector<FunctionMemoryWriteRange> intersection;
    intersection.reserve(std::min(
        destination.memory_definitely_written_ranges.size(),
        source.memory_definitely_written_ranges.size()));
    std::size_t left = 0u;
    std::size_t right = 0u;
    while (left < destination.memory_definitely_written_ranges.size() &&
           right < source.memory_definitely_written_ranges.size()) {
        const auto& first =
            destination.memory_definitely_written_ranges[left];
        const auto& second =
            source.memory_definitely_written_ranges[right];
        const auto begin = std::max(first.address, second.address);
        const auto first_end =
            static_cast<std::uint64_t>(first.address) + first.width;
        const auto second_end =
            static_cast<std::uint64_t>(second.address) + second.width;
        const auto end = std::min(first_end, second_end);
        if (static_cast<std::uint64_t>(begin) < end)
            intersection.push_back(
                {begin, static_cast<std::uint32_t>(end - begin)});
        if (first_end < second_end)
            ++left;
        else
            ++right;
    }
    if (intersection ==
        destination.memory_definitely_written_ranges)
        return false;
    destination.memory_definitely_written_ranges =
        std::move(intersection);
    return true;
}

enum class EvidenceProvenanceDomain : std::uint8_t {
    CallSite,
    Callee,
};

using EvidenceMembership = std::vector<std::size_t>;
using EvidenceTokenAssignments =
    std::map<EvidenceMembership, std::uint32_t>;

struct EvidenceFieldLayout {
    std::array<std::vector<std::int32_t>, 16u>
        register_saved_stack_slots;
    std::map<std::int32_t, std::vector<std::int32_t>>
        stack_saved_stack_slots;
    bool stack_tail_present = false;
    std::vector<std::int32_t> stack_tail_saved_stack_slots;
    std::map<std::uint32_t, std::vector<std::int32_t>>
        memory_saved_stack_slots;
    std::vector<std::int32_t> unresolved_stack_epoch_slots;
    std::vector<std::int32_t> unresolved_memory_epoch_slots;

    bool operator==(const EvidenceFieldLayout&) const = default;
};

struct SummaryEvidenceFieldLayout final {
    std::vector<std::size_t> register_epoch_slot_counts;
    std::vector<std::uint32_t> memory_addresses;
    std::vector<std::size_t> memory_epoch_slot_counts;
    std::size_t unresolved_stack_epoch_slot_count = 0u;
    std::size_t unresolved_memory_epoch_slot_count = 0u;
    std::vector<std::vector<std::int32_t>> register_epoch_topologies;
    std::vector<std::vector<std::int32_t>> memory_epoch_topologies;
    std::vector<std::int32_t> unresolved_stack_epoch_topology;
    std::vector<std::int32_t> unresolved_memory_epoch_topology;
    std::vector<std::int32_t> current_stack_epoch_mutation_topology;

    bool operator==(const SummaryEvidenceFieldLayout&) const = default;
};

template <typename Epoch>
[[nodiscard]] std::vector<std::int32_t>
capture_saved_stack_epoch_evidence_topology(const Epoch& root) {
    // This is layout only: it fixes evidence-field ordinals across private
    // alpha restore without placing concrete evidence into the shape.  The
    // delimiters make nested slot and unresolved-child form unambiguous.
    constexpr auto node_begin = std::numeric_limits<std::int32_t>::min();
    constexpr auto slots_begin = node_begin + 1;
    constexpr auto nested_begin = node_begin + 2;
    constexpr auto unresolved_nested_begin = node_begin + 3;
    std::vector<std::int32_t> topology;
    const auto append = [&](auto&& self, const auto& epoch) -> void {
        topology.push_back(node_begin);
        topology.push_back(epoch.present ? 1 : 0);
        topology.push_back(epoch.unresolved ? 1 : 0);
        topology.push_back(epoch.tracks_current_epoch ? 1 : 0);
        topology.push_back(epoch.candidate_payload_lost ? 1 : 0);
        topology.push_back(epoch.nested_saved_stack_alias_latent ? 1 : 0);
        topology.push_back(
            epoch.nested_saved_stack_alias_tracks_current_epoch ? 1 : 0);
        topology.push_back(slots_begin);
        topology.push_back(static_cast<std::int32_t>(epoch.slots.size()));
        for (const auto& slot : epoch.slots) {
            topology.push_back(slot.relative_slot);
            topology.push_back(nested_begin);
            topology.push_back(
                static_cast<std::int32_t>(slot.nested_epochs.size()));
            for (const auto& nested : slot.nested_epochs)
                self(self, nested);
        }
        topology.push_back(unresolved_nested_begin);
        topology.push_back(
            static_cast<std::int32_t>(
                epoch.unresolved_nested_epochs.size()));
        for (const auto& nested : epoch.unresolved_nested_epochs)
            self(self, nested);
    };
    append(append, root);
    return topology;
}

[[nodiscard]] SummaryEvidenceFieldLayout capture_summary_evidence_field_layout(
    const FunctionValueSummary& summary) {
    SummaryEvidenceFieldLayout layout;
    layout.register_epoch_slot_counts.reserve(summary.registers.size());
    layout.register_epoch_topologies.reserve(summary.registers.size());
    for (const auto& value : summary.registers)
        {
            layout.register_epoch_slot_counts.push_back(
                value.inventory_saved_stack_epoch.slots.size());
            layout.register_epoch_topologies.push_back(
                capture_saved_stack_epoch_evidence_topology(
                    value.inventory_saved_stack_epoch));
        }
    layout.memory_addresses.reserve(summary.memory_values.size());
    layout.memory_epoch_slot_counts.reserve(summary.memory_values.size());
    layout.memory_epoch_topologies.reserve(summary.memory_values.size());
    for (const auto& value : summary.memory_values) {
        layout.memory_addresses.push_back(value.address);
        layout.memory_epoch_slot_counts.push_back(
            value.inventory_saved_stack_epoch.slots.size());
        layout.memory_epoch_topologies.push_back(
            capture_saved_stack_epoch_evidence_topology(
                value.inventory_saved_stack_epoch));
    }
    layout.unresolved_stack_epoch_slot_count =
        summary.inventory_unresolved_stack_epoch.slots.size();
    layout.unresolved_memory_epoch_slot_count =
        summary.inventory_unresolved_memory_epoch.slots.size();
    layout.unresolved_stack_epoch_topology =
        capture_saved_stack_epoch_evidence_topology(
            summary.inventory_unresolved_stack_epoch);
    layout.unresolved_memory_epoch_topology =
        capture_saved_stack_epoch_evidence_topology(
            summary.inventory_unresolved_memory_epoch);
    layout.current_stack_epoch_mutation_topology =
        capture_saved_stack_epoch_evidence_topology(
            summary.current_stack_epoch_mutation_epoch);
    return layout;
}

[[nodiscard]] EvidenceFieldLayout capture_evidence_field_layout(
    const AbstractState& state) {
    EvidenceFieldLayout layout;
    const auto capture_saved_slots = [](const AbstractValue& value) {
        return capture_saved_stack_epoch_evidence_topology(
            value.inventory_saved_stack_epoch);
    };
    for (std::size_t index = 0u; index < state.registers.size(); ++index)
        layout.register_saved_stack_slots[index] =
            capture_saved_slots(state.registers[index]);
    for (const auto& [slot, value] : state.stack_values)
        layout.stack_saved_stack_slots.emplace(
            slot, capture_saved_slots(value));
    layout.stack_tail_present = state.stack_tail.present;
    if (state.stack_tail.present)
        layout.stack_tail_saved_stack_slots =
            capture_saved_slots(state.stack_tail.payload);
    for (const auto& [address, value] : state.memory_values)
        layout.memory_saved_stack_slots.emplace(
            address, capture_saved_slots(value));
    layout.unresolved_stack_epoch_slots =
        capture_saved_stack_epoch_evidence_topology(
            state.inventory_unresolved_stack_epoch);
    layout.unresolved_memory_epoch_slots =
        capture_saved_stack_epoch_evidence_topology(
            state.inventory_unresolved_memory_epoch);
    return layout;
}

template <typename Callback>
void for_each_evidence_set(InventoryCandidateCarrier& carrier,
                           Callback&& callback) {
    callback(EvidenceProvenanceDomain::CallSite, carrier.call_sites);
    callback(EvidenceProvenanceDomain::Callee, carrier.callees);
}

template <typename Callback>
void for_each_evidence_set(InventorySavedStackEpoch& epoch,
                           Callback&& callback) {
    for (auto& slot : epoch.slots) {
        for_each_evidence_set(slot.carrier, callback);
        for (auto& nested : slot.nested_epochs)
            for_each_evidence_set(nested, callback);
    }
    for_each_evidence_set(epoch.unresolved_candidate_carrier, callback);
    for (auto& nested : epoch.unresolved_nested_epochs)
        for_each_evidence_set(nested, callback);
}

template <typename Callback>
void for_each_evidence_set(AbstractValue& value, Callback&& callback) {
    callback(EvidenceProvenanceDomain::CallSite, value.call_sites);
    callback(EvidenceProvenanceDomain::Callee, value.callees);
    for_each_evidence_set(value.inventory_saved_stack_epoch, callback);
}

template <typename Callback>
void for_each_evidence_set(AbstractState& state, Callback&& callback) {
    for (auto& value : state.registers)
        for_each_evidence_set(value, callback);
    for (auto& [slot, value] : state.stack_values) {
        static_cast<void>(slot);
        for_each_evidence_set(value, callback);
    }
    if (state.stack_tail.present)
        for_each_evidence_set(state.stack_tail.payload, callback);
    for (auto& [address, value] : state.memory_values) {
        static_cast<void>(address);
        for_each_evidence_set(value, callback);
    }
    for_each_evidence_set(state.inventory_unresolved_stack_carrier, callback);
    for_each_evidence_set(state.inventory_unresolved_memory_carrier, callback);
    for_each_evidence_set(state.inventory_unresolved_stack_epoch, callback);
    for_each_evidence_set(state.inventory_unresolved_memory_epoch, callback);
}

[[nodiscard]] bool same_inventory_saved_stack_epoch_without_evidence(
    const InventorySavedStackEpoch& left,
    const InventorySavedStackEpoch& right);
[[nodiscard]] bool same_inventory_candidate_carrier_without_evidence(
    const InventoryCandidateCarrier& left,
    const InventoryCandidateCarrier& right);

// A truncated bounded candidate domain is semantic Top.  Its retained finite
// prefix is intentionally non-semantic: old persisted states and partially
// normalized intermediates must not split a lane, cache key, or comparison.
[[nodiscard]] bool same_inventory_candidate_domain(
    const std::vector<std::uint32_t>& left_values,
    const bool left_truncated,
    const std::vector<std::uint32_t>& right_values,
    const bool right_truncated) {
    return left_truncated == right_truncated &&
           (left_truncated || left_values == right_values);
}

[[nodiscard]] bool same_inventory_saved_stack_slot_without_evidence(
    const InventorySavedStackSlot& left,
    const InventorySavedStackSlot& right) {
    if (left.relative_slot != right.relative_slot ||
        !same_inventory_candidate_carrier_without_evidence(left.carrier,
                                                            right.carrier) ||
        left.nested_epochs.size() != right.nested_epochs.size())
        return false;
    for (std::size_t index = 0u; index < left.nested_epochs.size(); ++index) {
        if (!same_inventory_saved_stack_epoch_without_evidence(
                left.nested_epochs[index], right.nested_epochs[index]))
            return false;
    }
    return true;
}

[[nodiscard]] bool same_inventory_candidate_carrier_without_evidence(
    const InventoryCandidateCarrier& left,
    const InventoryCandidateCarrier& right) {
    return same_inventory_candidate_domain(
               left.inventory_code_pointer_values,
               left.inventory_code_pointer_values_truncated,
               right.inventory_code_pointer_values,
               right.inventory_code_pointer_values_truncated) &&
           same_inventory_candidate_domain(
               left.inventory_pc_relative_code_literal_values,
               left.inventory_pc_relative_code_literal_values_truncated,
               right.inventory_pc_relative_code_literal_values,
               right.inventory_pc_relative_code_literal_values_truncated) &&
           same_inventory_candidate_domain(
               left.pending_abi_scalar_values,
               left.pending_abi_scalar_values_truncated,
               right.pending_abi_scalar_values,
               right.pending_abi_scalar_values_truncated) &&
           left.contextual_candidate_dependency ==
               right.contextual_candidate_dependency;
}

[[nodiscard]] bool same_inventory_saved_stack_epoch_without_evidence(
    const InventorySavedStackEpoch& left,
    const InventorySavedStackEpoch& right) {
    if (left.present != right.present || left.unresolved != right.unresolved ||
        left.tracks_current_epoch != right.tracks_current_epoch ||
        left.candidate_payload_lost != right.candidate_payload_lost ||
        left.nested_saved_stack_alias_latent !=
            right.nested_saved_stack_alias_latent ||
        left.nested_saved_stack_alias_tracks_current_epoch !=
            right.nested_saved_stack_alias_tracks_current_epoch)
        return false;
    // Candidate Top is absorbing.  Old/intermediate retained children cannot
    // contribute semantic identity once the epoch is terminal; only
    // active/nested alias facts above remain observable.
    if (left.candidate_payload_lost) return true;
    if (!same_inventory_candidate_carrier_without_evidence(
            left.unresolved_candidate_carrier,
            right.unresolved_candidate_carrier) ||
        left.slots.size() != right.slots.size() ||
        left.unresolved_nested_epochs.size() !=
            right.unresolved_nested_epochs.size())
        return false;
    for (std::size_t index = 0u; index < left.slots.size(); ++index) {
        if (!same_inventory_saved_stack_slot_without_evidence(
                left.slots[index], right.slots[index]))
            return false;
    }
    for (std::size_t index = 0u;
         index < left.unresolved_nested_epochs.size();
         ++index) {
        if (!same_inventory_saved_stack_epoch_without_evidence(
                left.unresolved_nested_epochs[index],
                right.unresolved_nested_epochs[index]))
            return false;
    }
    return true;
}

[[nodiscard]] bool same_inventory_candidate_carrier_with_evidence(
    const InventoryCandidateCarrier& left,
    const InventoryCandidateCarrier& right) {
    return same_inventory_candidate_carrier_without_evidence(left, right) &&
           left.call_sites == right.call_sites && left.callees == right.callees;
}

[[nodiscard]] bool same_inventory_saved_stack_epoch_with_evidence(
    const InventorySavedStackEpoch& left,
    const InventorySavedStackEpoch& right) {
    if (left.present != right.present || left.unresolved != right.unresolved ||
        left.tracks_current_epoch != right.tracks_current_epoch ||
        left.candidate_payload_lost != right.candidate_payload_lost ||
        left.nested_saved_stack_alias_latent !=
            right.nested_saved_stack_alias_latent ||
        left.nested_saved_stack_alias_tracks_current_epoch !=
            right.nested_saved_stack_alias_tracks_current_epoch)
        return false;
    // Exact replay still sees root evidence, but terminal candidate semantics
    // have no meaningful residual slots or finite carrier prefix.
    if (left.candidate_payload_lost)
        return same_inventory_candidate_carrier_with_evidence(
            left.unresolved_candidate_carrier,
            right.unresolved_candidate_carrier);
    if (!same_inventory_candidate_carrier_with_evidence(
            left.unresolved_candidate_carrier,
            right.unresolved_candidate_carrier) ||
        left.slots.size() != right.slots.size() ||
        left.unresolved_nested_epochs.size() !=
            right.unresolved_nested_epochs.size())
        return false;
    for (std::size_t index = 0u; index < left.slots.size(); ++index) {
        const auto& left_slot = left.slots[index];
        const auto& right_slot = right.slots[index];
        if (left_slot.relative_slot != right_slot.relative_slot ||
            !same_inventory_candidate_carrier_with_evidence(
                left_slot.carrier, right_slot.carrier) ||
            left_slot.nested_epochs.size() !=
                right_slot.nested_epochs.size())
            return false;
        for (std::size_t nested = 0u;
             nested < left_slot.nested_epochs.size();
             ++nested) {
            if (!same_inventory_saved_stack_epoch_with_evidence(
                    left_slot.nested_epochs[nested],
                    right_slot.nested_epochs[nested]))
                return false;
        }
    }
    for (std::size_t index = 0u;
         index < left.unresolved_nested_epochs.size();
         ++index) {
        if (!same_inventory_saved_stack_epoch_with_evidence(
                left.unresolved_nested_epochs[index],
                right.unresolved_nested_epochs[index]))
            return false;
    }
    return true;
}

[[nodiscard]] bool same_abstract_value_without_evidence(
    const AbstractValue& left,
    const AbstractValue& right) {
    if (left.known != right.known || left.guarded != right.guarded ||
        left.complete != right.complete ||
        left.inventory_stack_derived != right.inventory_stack_derived ||
        (left.inventory_code_pointer_values_truncated
             ? false
             : left.inventory_code_pointer) !=
            (right.inventory_code_pointer_values_truncated
                 ? false
                 : right.inventory_code_pointer) ||
        (left.inventory_pc_relative_code_literal_values_truncated
             ? false
             : left.inventory_pc_relative_code_literal) !=
            (right.inventory_pc_relative_code_literal_values_truncated
                 ? false
                 : right.inventory_pc_relative_code_literal) ||
        !same_inventory_candidate_domain(
            left.inventory_code_pointer_values,
            left.inventory_code_pointer_values_truncated,
            right.inventory_code_pointer_values,
            right.inventory_code_pointer_values_truncated) ||
        !same_inventory_candidate_domain(
            left.inventory_pc_relative_code_literal_values,
            left.inventory_pc_relative_code_literal_values_truncated,
            right.inventory_pc_relative_code_literal_values,
            right.inventory_pc_relative_code_literal_values_truncated) ||
        left.contextual_candidate_dependency !=
            right.contextual_candidate_dependency ||
        left.inventory_stack_callback_loss_unresolved !=
            right.inventory_stack_callback_loss_unresolved ||
        left.values != right.values)
        return false;
    const auto& left_epoch = left.inventory_saved_stack_epoch;
    const auto& right_epoch = right.inventory_saved_stack_epoch;
    return same_inventory_saved_stack_epoch_without_evidence(
        left_epoch, right_epoch);
}

[[nodiscard]] bool same_saved_stack_epoch_shape(
    const InventorySavedStackEpoch& left,
    const InventorySavedStackEpoch& right);

[[nodiscard]] bool same_abstract_state_without_evidence(
    const AbstractState& left,
    const AbstractState& right) {
    if (left.stack_offsets != right.stack_offsets ||
        left.inventory_stack_offsets != right.inventory_stack_offsets ||
        left.inventory_stack_offset_candidates !=
            right.inventory_stack_offset_candidates ||
        left.stack_may_alias != right.stack_may_alias ||
        left.inventory_stack_may_alias != right.inventory_stack_may_alias ||
        left.inventory_vbr_relative != right.inventory_vbr_relative ||
        left.inventory_fixed_storage_reference !=
            right.inventory_fixed_storage_reference ||
        left.memory_write_unknown != right.memory_write_unknown ||
        left.memory_write_ranges != right.memory_write_ranges ||
        left.memory_definitely_written_ranges !=
            right.memory_definitely_written_ranges ||
        left.inventory_unresolved_saved_stack_alias_sources !=
            right.inventory_unresolved_saved_stack_alias_sources ||
        left.inventory_unresolved_saved_stack_alias_tracks_current_sources !=
            right.inventory_unresolved_saved_stack_alias_tracks_current_sources ||
        left.inventory_current_stack_epoch_alias_watcher !=
            right.inventory_current_stack_epoch_alias_watcher ||
        left.inventory_detached_stack_epoch_alias_watcher !=
            right.inventory_detached_stack_epoch_alias_watcher ||
        left.inventory_unresolved_stack_callback_loss !=
            right.inventory_unresolved_stack_callback_loss ||
        left.inventory_unresolved_memory_callback_loss !=
            right.inventory_unresolved_memory_callback_loss ||
        left.inventory_callback_loss_identity_truncated_sources !=
            right.inventory_callback_loss_identity_truncated_sources ||
        !same_inventory_candidate_carrier_without_evidence(
            left.inventory_unresolved_stack_carrier,
            right.inventory_unresolved_stack_carrier) ||
        !same_inventory_candidate_carrier_without_evidence(
            left.inventory_unresolved_memory_carrier,
            right.inventory_unresolved_memory_carrier) ||
        !same_inventory_saved_stack_epoch_without_evidence(
            left.inventory_unresolved_stack_epoch,
            right.inventory_unresolved_stack_epoch) ||
        !same_inventory_saved_stack_epoch_without_evidence(
            left.inventory_unresolved_memory_epoch,
            right.inventory_unresolved_memory_epoch))
        return false;
    for (std::size_t index = 0u; index < left.registers.size(); ++index) {
        if (!same_abstract_value_without_evidence(
                left.registers[index], right.registers[index]))
            return false;
    }
    if (left.stack_tail.present != right.stack_tail.present ||
        (left.stack_tail.present &&
         (left.stack_tail.lower_bound != right.stack_tail.lower_bound ||
          !same_abstract_value_without_evidence(
              left.stack_tail.payload, right.stack_tail.payload))))
        return false;
    if (left.stack_values.size() != right.stack_values.size() ||
        left.memory_values.size() != right.memory_values.size())
        return false;
    auto left_stack_value = left.stack_values.begin();
    auto right_stack_value = right.stack_values.begin();
    while (left_stack_value != left.stack_values.end()) {
        if (left_stack_value->first != right_stack_value->first ||
            !same_abstract_value_without_evidence(
                left_stack_value->second, right_stack_value->second))
            return false;
        ++left_stack_value;
        ++right_stack_value;
    }
    auto left_memory_value = left.memory_values.begin();
    auto right_memory_value = right.memory_values.begin();
    while (left_memory_value != left.memory_values.end()) {
        if (left_memory_value->first != right_memory_value->first ||
            !same_abstract_value_without_evidence(
                left_memory_value->second, right_memory_value->second))
            return false;
        ++left_memory_value;
        ++right_memory_value;
    }
    return true;
}

// One domain lens alpha-renames concrete evidence atoms by their complete
// membership signature across every bounded input that one evaluation can
// observe: ingress state and its private global/contextual summary overlays.
// This
// preserves the complete set equality/overlap/union algebra while making the
// physical state independent of actual root addresses and group cardinality.
// Atoms with an identical signature are represented by one token because
// every transfer observes them together; replay expands that token back to
// every concrete address before any result becomes visible.
class EvidenceProvenanceDomainLens final {
  public:
    [[nodiscard]] bool canonicalize(
        const std::span<std::set<std::uint32_t>*> set_fields,
        const std::span<std::vector<std::uint32_t>*> vector_fields,
        const std::span<const std::uint32_t> available_tokens,
        const std::unordered_set<std::uint32_t>&
            locally_observable_constants,
        const std::unordered_set<std::uint32_t>* const
            additional_locally_observable_constants = nullptr,
        const EvidenceTokenAssignments* const prior_assignments =
            nullptr) {
        std::map<std::uint32_t, EvidenceMembership> memberships;
        const auto observe_field =
            [&](const auto& evidence_values,
                const std::size_t field_index) {
                for (const auto evidence : evidence_values) {
                    auto& membership = memberships[evidence];
                    if (membership.empty() ||
                        membership.back() != field_index)
                        membership.push_back(field_index);
                }
            };
        for (std::size_t field_index = 0u;
             field_index < set_fields.size();
             ++field_index)
            observe_field(*set_fields[field_index], field_index);
        for (std::size_t field_index = 0u;
             field_index < vector_fields.size();
             ++field_index)
            observe_field(
                *vector_fields[field_index],
                set_fields.size() + field_index);
        std::map<EvidenceMembership, std::vector<std::uint32_t>>
            atoms_by_membership;
        for (auto& [concrete, membership] : memberships) {
            if (locally_observable_constants.contains(concrete) ||
                (additional_locally_observable_constants != nullptr &&
                 additional_locally_observable_constants->contains(
                     concrete)))
                continue;
            atoms_by_membership[std::move(membership)].push_back(
                concrete);
        }
        token_by_membership_ =
            prior_assignments == nullptr
                ? EvidenceTokenAssignments{}
                : *prior_assignments;
        required_tokens_ = token_by_membership_.size();
        for (const auto& [membership, concrete_atoms] :
             atoms_by_membership) {
            static_cast<void>(concrete_atoms);
            if (!token_by_membership_.contains(membership))
                ++required_tokens_;
        }
        if (required_tokens_ > available_tokens.size())
            return false;

        // A token may never alias input evidence. Tokens are also selected
        // outside every image/program address before this lens is built; the
        // local evaluator can therefore add real callsites/callees without
        // making reverse expansion ambiguous. Keep prior names reserved even
        // while their membership is temporarily absent: discovering a new,
        // lexicographically earlier membership must not renumber every
        // existing group and turn one monotone Forwarded context into a new
        // cache key.
        std::unordered_set<std::uint32_t> used_tokens;
        used_tokens.reserve(token_by_membership_.size());
        for (const auto& [membership, token] : token_by_membership_) {
            static_cast<void>(membership);
            if (!std::binary_search(
                    available_tokens.begin(),
                    available_tokens.end(),
                    token,
                    std::greater<std::uint32_t>{}) ||
                memberships.contains(token) ||
                !used_tokens.insert(token).second)
                return false;
        }
        auto next_token = available_tokens.begin();
        for (auto& [membership, concrete_atoms] :
             atoms_by_membership) {
            auto assignment = token_by_membership_.find(membership);
            if (assignment == token_by_membership_.end()) {
                while (next_token != available_tokens.end() &&
                       (used_tokens.contains(*next_token) ||
                        memberships.contains(*next_token)))
                    ++next_token;
                if (next_token == available_tokens.end()) {
                    required_tokens_ = used_tokens.size() + 1u;
                    return false;
                }
                const auto token = *next_token++;
                assignment = token_by_membership_
                                 .emplace(membership, token)
                                 .first;
                used_tokens.insert(token);
            }
            const auto token = assignment->second;
            for (const auto concrete : concrete_atoms)
                concrete_to_token_.emplace(concrete, token);
            if (!token_to_concrete_
                     .emplace(token, std::move(concrete_atoms))
                     .second)
                return false;
        }
        required_tokens_ = token_by_membership_.size();
        for (auto* const field : set_fields) {
            std::set<std::uint32_t> canonical;
            for (const auto concrete : *field) {
                const auto token = concrete_to_token_.find(concrete);
                canonical.insert(token == concrete_to_token_.end()
                                     ? concrete
                                     : token->second);
            }
            *field = std::move(canonical);
        }
        for (auto* const field : vector_fields) {
            std::vector<std::uint32_t> canonical;
            canonical.reserve(field->size());
            for (const auto concrete : *field) {
                const auto token = concrete_to_token_.find(concrete);
                canonical.push_back(token == concrete_to_token_.end()
                                        ? concrete
                                        : token->second);
            }
            std::sort(canonical.begin(), canonical.end());
            canonical.erase(
                std::unique(canonical.begin(), canonical.end()),
                canonical.end());
            *field = std::move(canonical);
        }
        return true;
    }

    void restore(std::set<std::uint32_t>& evidence) const {
        std::set<std::uint32_t> restored;
        for (const auto value : evidence) {
            const auto concrete = token_to_concrete_.find(value);
            if (concrete == token_to_concrete_.end()) {
                restored.insert(value);
            } else {
                restored.insert(concrete->second.begin(),
                                concrete->second.end());
            }
        }
        evidence = std::move(restored);
    }

    void restore(std::vector<std::uint32_t>& evidence) const {
        std::vector<std::uint32_t> restored;
        restored.reserve(evidence.size());
        for (const auto value : evidence) {
            const auto concrete = token_to_concrete_.find(value);
            if (concrete == token_to_concrete_.end()) {
                restored.push_back(value);
            } else {
                restored.insert(restored.end(),
                                concrete->second.begin(),
                                concrete->second.end());
            }
        }
        std::sort(restored.begin(), restored.end());
        restored.erase(
            std::unique(restored.begin(), restored.end()),
            restored.end());
        evidence = std::move(restored);
    }

    [[nodiscard]] std::size_t link_count() const noexcept {
        std::size_t links = 0u;
        for (const auto& [token, concrete] : token_to_concrete_) {
            static_cast<void>(token);
            links += concrete.size();
        }
        return links;
    }

    [[nodiscard]] std::size_t required_tokens() const noexcept {
        return required_tokens_;
    }

    [[nodiscard]] const EvidenceTokenAssignments& token_assignments()
        const noexcept {
        return token_by_membership_;
    }

  private:
    std::map<std::uint32_t, std::uint32_t> concrete_to_token_;
    std::map<std::uint32_t, std::vector<std::uint32_t>>
        token_to_concrete_;
    EvidenceTokenAssignments token_by_membership_;
    std::size_t required_tokens_ = 0u;
};

struct ContextualCallSiteKey final {
    std::uint32_t call_site = 0u;
    std::uint32_t callee = 0u;

    auto operator<=>(const ContextualCallSiteKey&) const = default;
};

struct ContextualBoundSummary final {
    AbstractState input;
    FunctionValueSummary summary;
};

using ContextualSummaryBindings =
    std::map<ContextualCallSiteKey,
             std::vector<ContextualBoundSummary>>;

struct ContextualBoundSummaryView final {
    const AbstractState* input = nullptr;
    const FunctionValueSummary* summary = nullptr;
};

using ContextualSummaryBindingViews =
    std::map<ContextualCallSiteKey,
             std::vector<ContextualBoundSummaryView>>;

[[nodiscard]] ContextualSummaryBindings
materialize_contextual_summary_bindings(
    const ContextualSummaryBindingViews& views) {
    ContextualSummaryBindings bindings;
    for (const auto& [key, source] : views) {
        auto& destination = bindings[key];
        destination.reserve(source.size());
        for (const auto& view : source) {
            if (view.input == nullptr || view.summary == nullptr)
                throw std::logic_error(
                    "Contextual-Summary-View verlor ihren Besitzer.");
            destination.push_back({*view.input, *view.summary});
        }
        if (destination.empty()) bindings.erase(key);
    }
    return bindings;
}

class EvidenceProvenanceLens final {
  public:
    EvidenceProvenanceLens(
        AbstractState ingress,
        const std::set<std::uint32_t>* const isolated_call_sites,
        const std::span<const std::uint32_t> available_tokens,
        const std::unordered_set<std::uint32_t>&
            locally_observable_call_sites,
        const std::unordered_set<std::uint32_t>&
            locally_observable_callees,
        std::map<std::uint32_t, FunctionValueSummary> summaries,
        std::optional<ContextualSummaryBindings>
            contextual_summaries = std::nullopt,
        const EvidenceTokenAssignments* const
            prior_call_site_assignments = nullptr,
        const EvidenceTokenAssignments* const
            prior_callee_assignments = nullptr)
        : ingress_(std::move(ingress)),
          summaries_(std::move(summaries)),
          contextual_summaries_(std::move(contextual_summaries)),
          isolated_(isolated_call_sites != nullptr) {
        if (isolated_)
            isolated_call_sites_ = *isolated_call_sites;
        std::vector<std::set<std::uint32_t>*> call_site_fields;
        std::vector<std::set<std::uint32_t>*> callee_fields;
        std::vector<std::vector<std::uint32_t>*>
            summary_callee_fields;
        for_each_evidence_set(
            ingress_,
            [&](const EvidenceProvenanceDomain domain,
                std::set<std::uint32_t>& evidence) {
                (domain == EvidenceProvenanceDomain::CallSite
                     ? call_site_fields
                     : callee_fields)
                    .push_back(&evidence);
            });
        if (isolated_)
            call_site_fields.push_back(&isolated_call_sites_);
        const auto collect_summary = [&](auto& summary) {
            const auto collect_epoch = [&](auto&& self, auto& epoch) -> void {
                for (auto& slot : epoch.slots) {
                    callee_fields.push_back(&slot.carrier.callees);
                    for (auto& nested : slot.nested_epochs)
                        self(self, nested);
                }
                callee_fields.push_back(
                    &epoch.unresolved_candidate_carrier.callees);
                for (auto& nested : epoch.unresolved_nested_epochs)
                    self(self, nested);
            };
            callee_fields.push_back(
                &summary.inventory_unresolved_stack_carrier.callees);
            callee_fields.push_back(
                &summary.inventory_unresolved_memory_carrier.callees);
            callee_fields.push_back(
                &summary.current_stack_epoch_mutation_carrier.callees);
            collect_epoch(collect_epoch,
                          summary.inventory_unresolved_stack_epoch);
            collect_epoch(collect_epoch,
                          summary.inventory_unresolved_memory_epoch);
            collect_epoch(collect_epoch,
                          summary.current_stack_epoch_mutation_epoch);
            for (auto& value : summary.registers) {
                summary_callee_fields.push_back(&value.evidence_callees);
                collect_epoch(collect_epoch,
                              value.inventory_saved_stack_epoch);
            }
            for (auto& value : summary.memory_values) {
                callee_fields.push_back(
                    &value.inventory_candidate_carrier.callees);
                collect_epoch(collect_epoch,
                              value.inventory_saved_stack_epoch);
            }
        };
        const auto collect_summary_callee_fields =
            [&](auto& summary_map) {
            for (auto& [address, summary] : summary_map) {
                static_cast<void>(address);
                collect_summary(summary);
            }
        };
        collect_summary_callee_fields(summaries_);
        if (contextual_summaries_.has_value()) {
            for (auto& [key, bindings] :
                 *contextual_summaries_) {
                static_cast<void>(key);
                for (auto& binding : bindings) {
                    for_each_evidence_set(
                        binding.input,
                        [&](const EvidenceProvenanceDomain domain,
                            std::set<std::uint32_t>& evidence) {
                            (domain ==
                                     EvidenceProvenanceDomain::CallSite
                                 ? call_site_fields
                                 : callee_fields)
                                .push_back(&evidence);
                        });
                    collect_summary(binding.summary);
                }
            }
        }
        valid_ = call_sites_.canonicalize(
                     call_site_fields,
                     {},
                     available_tokens,
                     locally_observable_call_sites,
                     nullptr,
                     prior_call_site_assignments) &&
                 callees_.canonicalize(
                     callee_fields,
                     summary_callee_fields,
                     available_tokens,
                     locally_observable_callees,
                     nullptr,
                     prior_callee_assignments);
    }

    [[nodiscard]] bool valid() const noexcept {
        return valid_;
    }

    [[nodiscard]] const AbstractState& ingress() const noexcept {
        return ingress_;
    }

    [[nodiscard]] const std::set<std::uint32_t>* isolated_call_sites()
        const noexcept {
        return isolated_ ? &isolated_call_sites_ : nullptr;
    }

    [[nodiscard]] const std::map<std::uint32_t,
                                 FunctionValueSummary>*
    summaries() const noexcept {
        return &summaries_;
    }

    [[nodiscard]] const ContextualSummaryBindings*
    contextual_summaries() const noexcept {
        return contextual_summaries_.has_value()
                   ? &*contextual_summaries_
                   : nullptr;
    }

    void restore(AbstractState& state) const {
        for_each_evidence_set(
            state,
            [&](const EvidenceProvenanceDomain domain,
                std::set<std::uint32_t>& evidence) {
                (domain == EvidenceProvenanceDomain::CallSite
                     ? call_sites_
                     : callees_)
                    .restore(evidence);
            });
    }

    void restore_call_sites(std::vector<std::uint32_t>& evidence) const {
        call_sites_.restore(evidence);
    }

    void restore_callees(std::vector<std::uint32_t>& evidence) const {
        callees_.restore(evidence);
    }

    void restore_callees(std::set<std::uint32_t>& evidence) const {
        callees_.restore(evidence);
    }

    void restore(InterproceduralTargetResolution& resolution) const {
        restore_call_sites(resolution.call_sites);
        restore_callees(resolution.callees);
    }

    [[nodiscard]] std::size_t link_count() const noexcept {
        return call_sites_.link_count() + callees_.link_count();
    }

    [[nodiscard]] std::size_t required_tokens() const noexcept {
        return std::max(call_sites_.required_tokens(),
                        callees_.required_tokens());
    }

    [[nodiscard]] const EvidenceTokenAssignments&
    call_site_token_assignments() const noexcept {
        return call_sites_.token_assignments();
    }

    [[nodiscard]] const EvidenceTokenAssignments&
    callee_token_assignments() const noexcept {
        return callees_.token_assignments();
    }

  private:
    AbstractState ingress_;
    std::map<std::uint32_t, FunctionValueSummary> summaries_;
    std::optional<ContextualSummaryBindings> contextual_summaries_;
    std::set<std::uint32_t> isolated_call_sites_;
    EvidenceProvenanceDomainLens call_sites_;
    EvidenceProvenanceDomainLens callees_;
    bool isolated_ = false;
    bool valid_ = false;
};

struct InventoryStackOffsetLossDiagnostic {
    const AbstractState& state;
    std::uint32_t site = 0u;
    std::optional<std::int32_t> before;

    ~InventoryStackOffsetLossDiagnostic() {
        if (!analyzer_stack_diagnostics_enabled() || !before.has_value() ||
            state.inventory_stack_offsets[15u].has_value() ||
            !state.inventory_stack_offset_candidates[15u].empty())
            return;
        emit_bounded_analyzer_diagnostic(
            detailed_analyzer_diagnostic_kind_inventory_sp_loss,
            site,
            static_cast<std::uint32_t>(*before),
            0u,
            static_cast<std::uint8_t>(state[15u].inventory_stack_derived),
            [&] {
                std::fprintf(stderr,
                             "KATANA_ANALYZER_INVENTORY_SP_LOSS site=0x%08X "
                             "before=%d derived=%u\n",
                             static_cast<unsigned int>(site),
                             *before,
                             state[15u].inventory_stack_derived);
            });
    }
};

